let whiteShare=50;
function paintEvaluation(){const canvas=$('evalCanvas'),ctx=canvas.getContext('2d'),height=canvas.height,width=canvas.width,whiteHeight=height*whiteShare/100;ctx.fillStyle='#000';ctx.fillRect(0,0,width,height);ctx.fillStyle='#fff';ctx.fillRect(0,flipped?0:height-whiteHeight,width,whiteHeight)}
function updateEvaluation(result){let bar=$('evalBar'),label=$('evalNumber');if(result.status==='unavailable'){label.textContent='—';bar.setAttribute('aria-valuetext','Evaluation unavailable on this device');return}if(result.status!=='ready'){label.textContent='…';bar.setAttribute('aria-valuetext','Analyzing position');return}let value=result.value,white=result.kind==='mate'?(value>=0?100:0):50+100/Math.PI*Math.atan(value/250);whiteShare=white;paintEvaluation();label.textContent=result.kind==='mate'?`${value<0?'−':''}M${Math.abs(value)}`:`${value>0?'+':value<0?'−':''}${(Math.abs(value)/100).toFixed(1)}`;bar.setAttribute('aria-valuenow',String(Math.round(white)));bar.setAttribute('aria-valuetext',result.kind==='mate'?`${value<0?'Black':'White'} has mate in ${Math.abs(value)}`:`${value>0?'White':value<0?'Black':'Neither side'} favored ${Math.abs(value/100).toFixed(1)}`)}
let evaluationEnabled=false;
function toggleEvaluation(){const enabled=evaluationEnabled;$('evalBar').hidden=!enabled;$('board').closest('.board-column').classList.toggle('with-evaluation',enabled);$('evalNumber').hidden=!enabled;if(enabled)paintEvaluation();$('evalToggle').setAttribute('aria-pressed',String(enabled));$('evalToggle').firstChild.textContent=`EVALUATION: ${enabled?'ON':'OFF'} `;if(enabled){evaluator.start();if(current)evaluator.setPosition(current,idx)}else evaluator.stop()}
$('evalToggle').addEventListener('click',()=>{evaluationEnabled=!evaluationEnabled;toggleEvaluation()});
function populateCollections(){const labels={fischer:'1972 · Fischer – Spassky',world2013:'2013 · Carlsen – Anand',world2014:'2014 · Carlsen – Anand',world2016:'2016 · Carlsen – Karjakin',world2018:'2018 · Carlsen – Caruana',world2021:'2021 · Carlsen – Nepomniachtchi',world2023:'2023 · Ding – Nepomniachtchi',world2024:'2024 · Ding – Gukesh'};let group=document.createElement('optgroup');group.label='WORLD CHAMPIONSHIP COLLECTIONS';for(const id of championshipOrder){const entry=archive.find(a=>a.id===id);let option=document.createElement('option');option.value=id;option.textContent=`${entry?entry.label:labels[id]} · ${builtin[id].length} games`;group.append(option)}collection.append(group);let other=document.createElement('optgroup');other.label='OTHER COLLECTIONS';let option=document.createElement('option');option.value='gukesh';option.textContent=`Gukesh – Sindarov · ${builtin.gukesh.length} games`;other.append(option);let importedOption=document.createElement('option');importedOption.id='importOption';importedOption.value='imported';importedOption.disabled=!imported.length;importedOption.textContent=imported.length?`Imported PGN · ${imported.length} games`:'Imported PGN';other.append(importedOption);collection.append(other)}

function clean(v){return v&&v!=='?'&&!v.includes('??')?v:''}function player(v){if(!v)return 'Unknown player';let a=v.split(',');return a.length>1?`${a.slice(1).join(',').trim()} ${a[0].trim()}`:v}
function formatDate(v){if(!v||v.includes('?'))return '';let [y,m,d]=v.split('.').map(Number);if(!y||!m||!d)return v.replaceAll('.',' ');return new Date(y,m-1,d).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}
let shuffleOn=false,shuffleCycleStarted=false;
function makeBag(excludeCurrent=false){bag=[...games.keys()];const currentIndex=games.indexOf(current);if(excludeCurrent&&currentIndex>=0)bag=bag.filter(i=>i!==currentIndex);for(let i=bag.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}if(!excludeCurrent&&bag.length>1&&bag[0]===currentIndex){let j=1+Math.floor(Math.random()*(bag.length-1));[bag[0],bag[j]]=[bag[j],bag[0]]}shuffleCycleStarted=true}
function showGame(gameIndex){try{if(!games[gameIndex].positions)games[gameIndex]=prepare(games[gameIndex])}catch(e){$('notice').textContent=`A game could not be read: ${e.message}`;games.splice(gameIndex,1);bag=bag.filter(i=>i!==gameIndex).map(i=>i>gameIndex?i-1:i);if(games.length)nextGame();return}current=games[gameIndex];idx=0;flipped=false;render();schedule()}
function nextGame(){if(!games.length)return;let gameIndex;if(shuffleOn){if(!shuffleCycleStarted||!bag.length)makeBag();gameIndex=bag.shift()}else{let currentIndex=games.indexOf(current);gameIndex=currentIndex<0?0:(currentIndex+1)%games.length;if(shuffleCycleStarted)bag=bag.filter(i=>i!==gameIndex)}showGame(gameIndex)}
$('shuffleToggle').addEventListener('click',()=>{shuffleOn=!shuffleOn;const button=$('shuffleToggle');button.setAttribute('aria-pressed',String(shuffleOn));button.firstChild.textContent=`SHUFFLE: ${shuffleOn?'ON':'OFF'} `;if(shuffleOn&&!shuffleCycleStarted)makeBag(true)});
const portraitPhotos={fischer:'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Bobby_Fischer_1972.jpg/250px-Bobby_Fischer_1972.jpg',spassky:'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/IBM-schaaktoernooi_Boris_Spasski%2C_Bestanddeelnr_923-7139.jpg/330px-IBM-schaaktoernooi_Boris_Spasski%2C_Bestanddeelnr_923-7139.jpg',gukesh:'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Gukesh_in_2024_%28cropped%29.jpg/250px-Gukesh_in_2024_%28cropped%29.jpg',sindarov:'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Javokhir_Sindarov_%28cropped%29.jpg/250px-Javokhir_Sindarov_%28cropped%29.jpg',carlsen:'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/World_Chess_Championship_2021%2C_game_07%2C_Magnus_Carlsen_%28cropped%29.jpg/250px-World_Chess_Championship_2021%2C_game_07%2C_Magnus_Carlsen_%28cropped%29.jpg',anand:'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Viswanathan_Anand_%28cropped%29.jpg/250px-Viswanathan_Anand_%28cropped%29.jpg',karjakin:'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Karjakin_Sergey_%2830334901886%29_%28cropped%29.jpg/250px-Karjakin_Sergey_%2830334901886%29_%28cropped%29.jpg',caruana:'https://upload.wikimedia.org/wikipedia/commons/0/02/Caruana_at_the_FIDE_World_FR_Chess_Championship_2019_%28cropped_v2%29.jpg',nepomniachtchi:'https://upload.wikimedia.org/wikipedia/commons/6/67/World_Chess_Championship_2021%2C_game_07%2C_Ian_Nepomniachtchi_%28cropped%29.jpg',ding:'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Ding_Liren_in_2024_%28cropped%29.jpg/250px-Ding_Liren_in_2024_%28cropped%29.jpg'};
for(const portrait of historicalPortraits)portraitPhotos[portrait.key]=portrait.src;
const credits=document.createElement('details');credits.className='photo-credits';const summary=document.createElement('summary');summary.textContent='Historical player image credits';credits.append(summary);const creditList=document.createElement('div');for(const item of historicalPortraits){let row=document.createElement('div');row.append(`${item.name}: ${item.author} · `);let source=document.createElement('a');source.href=item.source;source.target='_blank';source.rel='noopener noreferrer';source.textContent='Source';row.append(source,' · ');if(item.license.startsWith('http')){let license=document.createElement('a');license.href=item.license;license.target='_blank';license.rel='noopener noreferrer';license.textContent='License';row.append(license)}else row.append(item.license);row.append(' · displayed in grayscale and cropped');creditList.append(row)}credits.append(creditList);$('notice').before(credits);
function setPortrait(id,name){let el=$(id),key=/\bfischer\b/i.test(name||'')?'fischer':/\bspassk(?:y|i)\b/i.test(name||'')?'spassky':/\bgukesh\b/i.test(name||'')?'gukesh':/\bsindarov\b/i.test(name||'')?'sindarov':/\bcarlsen\b/i.test(name||'')?'carlsen':/\banand\b/i.test(name||'')?'anand':/\bkarjakin\b/i.test(name||'')?'karjakin':/\bcaruana\b/i.test(name||'')?'caruana':/\bnepomniachtchi\b/i.test(name||'')?'nepomniachtchi':/\b(?:ding|liren)\b/i.test(name||'')?'ding':null;if(!key){let surname=(name||'').split(',')[0].trim().toLowerCase();let aliases={kortschnoj:'korchnoi',korchnoj:'korchnoi',kortsjnoj:'korchnoi',akopjan:'akopian',kasimdjanov:'kasimdzhanov'};surname=aliases[surname]||surname;let match=historicalPortraits.find(p=>p.key===surname);if(match)key=match.key}if(el.dataset.player===String(key))return;el.dataset.player=String(key);el.querySelector('img')?.remove();el.classList.remove('has-photo');if(!key)return;let img=document.createElement('img');img.alt='';img.decoding='async';img.className=key;img.onload=()=>{if(img.isConnected)el.classList.add('has-photo')};img.onerror=()=>{if(img.isConnected){img.remove();el.classList.remove('has-photo')}};img.src=portraitPhotos[key];el.append(img)}
function render(animate=false){if(!current)return;let {tags,moves,positions}=current,p=positions[idx],board=$('board');if(board.children.length!==64){board.replaceChildren();for(let n=0;n<64;n++){let square=document.createElement('div');square.append(document.createElement('span'));board.append(square)}}p.state.b.forEach((_,screenIndex)=>{let i=flipped?63-screenIndex:screenIndex,piece=p.state.b[i],square=board.children[screenIndex],coord=square.firstElementChild;square.className='square'+(((Math.floor(i/8)+i%8)%2)?' dark-square':'')+((i===p.from||i===p.to)?' last':'');coord.className='coord';coord.textContent=(screenIndex%8===0?String(8-Math.floor(i/8)):'')+(screenIndex>=56?'abcdefgh'[i%8]:'');let old=square.querySelector('.piece');if((old?.dataset.piece||'')!==(piece||'')){if(old)old.remove();if(piece){let q=document.createElement('img');q.className='piece '+(piece===piece.toUpperCase()?'white':'black');q.dataset.piece=piece;q.src=`pieces/w${piece.toUpperCase()}.svg`;q.alt='';q.draggable=false;square.append(q);if(animate&&i===p.to&&p.from!==null&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){let dx=(p.from%8)-(p.to%8),dy=Math.floor(p.from/8)-Math.floor(p.to/8);q.animate([{transform:`translate(${dx*100*(flipped?-1:1)}%, ${dy*100*(flipped?-1:1)}%)`},{transform:'translate(0,0)'}],{duration:300,easing:'ease-out'})}}}});$('orientationLabel').textContent=flipped?'BLACK AT THE BOTTOM':'WHITE AT THE BOTTOM';$('evalBar').classList.toggle('flipped',flipped);paintEvaluation();if(evaluationEnabled)evaluator.setPosition(current,idx);$('event').textContent=clean(tags.Event)||'Chess game';$('meta').textContent=[clean(tags.Site),formatDate(tags.Date),clean(tags.EventType),clean(tags.Round)?`${tags._Tournament?'Round':/tiebreak/i.test(tags.EventType||'')?'Tiebreak game':'Game'} ${tags.Round}`:''].filter(Boolean).join('  ·  ');$('whiteName').textContent=player(tags.White);$('blackName').textContent=player(tags.Black);setPortrait('whitePortrait',tags.White);setPortrait('blackPortrait',tags.Black);$('whiteClock').textContent=p.clocks[0]||'';$('blackClock').textContent=p.clocks[1]||'';$('moveLabel').textContent=idx?`MOVE ${Math.ceil(idx/2)}${idx%2?' · WHITE':' · BLACK'}  ${moves[idx-1].san}`:'STARTING POSITION';$('gamecount').textContent=`NOW PLAYING ${games.indexOf(current)+1} OF ${games.length}`;let score=scoreFor(current,idx===moves.length);$('matchScore').hidden=!score;if(score){$('scoreLabel').textContent=score.finished?'MATCH SCORE AFTER GAME':'MATCH SCORE BEFORE GAME';let [whiteScore,blackScore]=score.main.split(' – ');$('scoreValue').textContent=`${player(tags.White)} ${whiteScore} – ${player(tags.Black)} ${blackScore}`;$('tieScore').textContent=score.tie?'TIEBREAK '+score.tie:'';}let finalResult=tags.Result==='1/2-1/2'?'½ – ½':(['1-0','0-1'].includes(tags.Result)?tags.Result.replace('-', ' – '):'');$('result').textContent=idx===moves.length?`FINAL RESULT  ·  ${finalResult||'Unknown'}`:'THE GAME IS UNDERWAY';$('boardResult').hidden=idx!==moves.length||!finalResult;$('boardResult').replaceChildren();$('boardResult').classList.toggle('forfeit',!moves.length);let resultLine=document.createElement('span');resultLine.textContent=finalResult;$('boardResult').append(resultLine);if(!moves.length){let forfeitLine=document.createElement('span');forfeitLine.textContent='FORFEIT';$('boardResult').append(forfeitLine)}let seek=$('progressSeek');seek.max=Math.max(1,moves.length);seek.disabled=!moves.length;seek.value=idx;seek.style.setProperty('--progress',`${moves.length?idx/moves.length*100:100}%`);seek.setAttribute('aria-valuetext',`Move ${idx} of ${moves.length}`);$('toggle').textContent=playing?'❚❚':'▶';$('toggle').setAttribute('aria-label',playing?'Pause':'Play');for(const id of ['prev','next']){$(id).style.visibility=playing?'hidden':'visible';$(id).disabled=playing}}
function schedule(){clearTimeout(timer);if(!playing||settings.open||help.open||!current)return;timer=setTimeout(()=>{if(idx<current.moves.length){idx++;render(true);schedule()}else nextGame()},(idx===current.moves.length?2*+speed.value:+speed.value)*1000)}
async function keepAwake(){try{if('wakeLock'in navigator)wake=await navigator.wakeLock.request('screen')}catch{}}
async function loadCollection(){let key=collection.value;let source=key==='imported'?imported:key==='championships'?championshipOrder.flatMap(id=>builtin[id]):key==='nonworld'?[...builtin.gukesh,...imported]:key==='all'?[...championshipOrder.flatMap(id=>builtin[id]),...builtin.gukesh,...imported]:key==='carlsen'?[2013,2014,2016,2018,2021].flatMap(y=>builtin['world'+y]):key==='ding'?[2023,2024].flatMap(y=>builtin['world'+y]):builtin[key]||[];let errors=[];games=[];if(key==='championships'||key==='all')games=source.slice();else for(const g of source){try{games.push(prepare(g))}catch(e){errors.push(`${g.tags.Event||'Game'}: ${e.message}`)}}$('notice').textContent=errors.length?`${games.length} playable; ${errors.length} could not be read. ${errors[0]}`:'';if(!games.length){$('notice').textContent='No playable standard chess games found. Choose another collection or file.';return false}bag=[];shuffleCycleStarted=false;current=null;playing=true;nextGame();return true}
$('helpButton').onclick=()=>{clearTimeout(timer);help.showModal()};help.addEventListener('close',schedule);$('settingsButton').onclick=$('openSettings').onclick=()=>{clearTimeout(timer);settings.showModal();collection.focus()};settings.addEventListener('close',schedule);$('apply').onclick=()=>{if(loadCollection()){settings.close();keepAwake()}};$('toggle').onclick=()=>{playing=!playing;render();schedule();if(playing)keepAwake()};$('prev').onclick=()=>{if(playing)return;idx=Math.max(0,idx-1);render()};$('next').onclick=()=>{if(playing)return;let old=idx;idx=Math.min(current.moves.length,idx+1);render(idx>old)};$('skip').onclick=()=>{playing=true;nextGame()};$('flip').onclick=()=>{flipped=!flipped;render()};$('restart').onclick=()=>{idx=0;render();schedule()};$('nextCollection').onclick=()=>{const key=collection.value;const other=['gukesh',...(imported.length?['imported']:[])];const options=(key==='nonworld'||other.includes(key))?other:key==='all'?[...championshipOrder,...other]:championshipOrder;const i=options.indexOf(key);collection.value=options[(i+1)%options.length];loadCollection()};speed.oninput=()=>$('speedValue').textContent=speed.value;$('progressSeek').oninput=e=>{if(!current)return;idx=Math.max(0,Math.min(current.moves.length,Number(e.target.value)));render();schedule()};
$('file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let t=await f.text();imported=parsePGN(t);if(!imported.length){$('notice').textContent='No playable standard-chess games found in that file.';return}$('importOption').disabled=false;$('importOption').textContent=`${f.name} · ${imported.length} games`;collection.value='imported';$('notice').textContent=`Loaded ${imported.length} game records. Choose Start playing.`;try{localStorage.setItem('chess-jukebox-pgn',t)}catch{}}catch{$('notice').textContent='Unable to read that file.'}};
document.addEventListener('keydown',e=>{if(settings.open||help.open)return;if(!playing&&document.activeElement===document.body&&e.key==='ArrowLeft'){e.preventDefault();$('prev').click()}else if(!playing&&document.activeElement===document.body&&e.key==='ArrowRight'){e.preventDefault();$('next').click()}else if((e.key===' '&&document.activeElement===document.body)||e.key==='MediaPlayPause'){e.preventDefault();$('toggle').click()}else if(e.key==='Escape'||e.key==='Backspace'){$('settingsButton').click()}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&playing)keepAwake()});
try{let saved=localStorage.getItem('chess-jukebox-pgn');if(saved)imported=parsePGN(saved)}catch{}
try{let names=['fischer','gukesh','world2013','world2014','world2016','world2018','world2021','world2023','world2024',...archive.map(x=>x.id)];let responses=await Promise.all(names.map(x=>fetch(`${archive.some(a=>a.id===x)?'archive/':''}${x}.pgn`).then(r=>{if(!r.ok)throw Error('Could not load the included games');return r.text()})));builtin=Object.fromEntries(names.map((name,i)=>[name,parsePGN(responses[i])]));for(const entry of archive){for(const g of builtin[entry.id]){let raw=g.tags.Event||'';g.tags.Event=entry.label.split(' · ')[0];if(/Rapid|Playoffs|g\/25|g\/15|25'/i.test(raw))g.tags.EventType='Rapid tiebreak';else if(/Sudden Death/i.test(raw))g.tags.EventType='Blitz tiebreak';else if(entry.kind==='match')g.tags.EventType='Classical';if(entry.kind==='tournament')g.tags._Tournament='yes'}if(entry.kind==='match')attachMatchScores(builtin[entry.id],entry.id)}for(const name of names)if(name==='fischer'||name.startsWith('world'))attachMatchScores(builtin[name],name);championshipOrder=[...archive.map(a=>a.id),'fischer','world2013','world2014','world2016','world2018','world2021','world2023','world2024'].sort((a,b)=>{let date=id=>{let d=builtin[id]?.[0]?.tags.Date||'';let year=archive.find(x=>x.id===id)?.year||(id==='fischer'?'1972':id.replace('world',''));return /^\d{4}/.test(d)?d.replace(/\?/g,'0'):year+'.00.00'};return date(a).localeCompare(date(b))||a.localeCompare(b)});populateCollections();await loadCollection();keepAwake()}catch(e){$('result').textContent='UNABLE TO LOAD THE INCLUDED GAMES';console.error(e)}
